// GUI Event Graphs for unit U18_GUI

// Graph nodes and edges representing UI events and follow-on events
// Nodes: Screen states, Widget interactions
// Edges: Triggered by user actions or system events

// 1. Display FiO2 prior to patient inhale limb
Node DisplayFiO2 {
    Event: ShowFiO2Screen
    Follows: LoginSuccess
    Outputs: FiO2ValueDisplayed
}

// 2. Set PIP from 5-55 cmH2O with increments of 1 cmH2O
Node SetPIP {
    Event: OpenPIPSettings
    Follows: DisplayFiO2
    Outputs: PIPSliderVisible
    Inputs: SliderMin=5, SliderMax=55, Step=1
}

// 3. Detect controller shutdown
Node DetectShutdown {
    Event: ControllerShutdown
    Follows: AnyScreen
    Outputs: ShutdownNotificationDisplayed
}

// 4. "Rise time" parameter in specific modes
Node RiseTimeControl {
    Event: EnterModeAssistControlPCV
    Follows: SetPIP
    Outputs: RiseTimeParameterVisible
    Inputs: Mode="Assist/Control PCV"
}

// 5. Set "rise parameter" in range 0..20% of breath cycle time
Node SetRiseParameter {
    Event: AdjustRiseTime
    Follows: RiseTimeControl
    Outputs: RiseTimeSet
    Inputs: ParameterRange=0..20
}

// 6. Specify assist/control with pressure controlled ventilation mode
Node AssistControlPCV {
    Event: SelectAssistControlPCVMode
    Follows: SetRiseParameter
    Outputs: AssistControlModeActive
}

// Navigation and blocking modal boxes
Edge LoginSuccess -> ShowFiO2Screen
Edge ShowFiO2Screen -> OpenPIPSettings
Edge OpenPIPSettings -> RiseTimeControl
Edge RiseTimeControl -> AdjustRiseTime
Edge AdjustRiseTime -> SelectAssistControlPCVMode
Edge AnyScreen -> ShutdownNotificationDisplayed (on ControllerShutdown)

// Modal box blocking background interactions
ModalBox ShutdownNotification {
    Trigger: ControllerShutdown
    Blocks: AllScreensExcept(ShutdownNotification)
}
